class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        tokens = tokens[:]
        while len(tokens) > 1:
            for i, t in enumerate(tokens):
                if t in "+-*/" and len(t) == 1:
                    a, b = int(tokens[i - 2]), int(tokens[i - 1])
                    if t == "+":
                        result = a + b
                    elif t == "-":
                        result = a - b
                    elif t == "*":
                        result = a * b
                    else:
                        result = int(a / b)
                    tokens[i - 2:i + 1] = [str(result)]
                    break
        return int(tokens[0])
